let today_local = startofday(datetime_utc_to_local(now(), "Europe/Berlin"));
let from_utc = datetime_local_to_utc(today_local, "Europe/Berlin");
let to_utc   = datetime_local_to_utc(today_local + 1d, "Europe/Berlin");
DayAheadPrice()
| where ts >= from_utc and ts < to_utc
| top 5 by Price_ct_kWh asc
| project Time_local, Price_ct_kWh, Price_EUR_MWh




let today_local = startofday(datetime_utc_to_local(now(), "Europe/Berlin"));
let from_utc = datetime_local_to_utc(today_local, "Europe/Berlin");
let to_utc   = datetime_local_to_utc(today_local + 1d, "Europe/Berlin");
let day = DayAheadPrice() | where ts >= from_utc and ts < to_utc;
day
| summarize Avg_ct_kWh = round(avg(Price_ct_kWh), 2), QuarterHours = count()
    by Hour_local = bin(Time_local, 1h)
| top 3 by Avg_ct_kWh asc
| extend DayMin = toscalar(day | summarize round(min(Price_ct_kWh), 2)),
         DayAvg = toscalar(day | summarize round(avg(Price_ct_kWh), 2)),
         DayMax = toscalar(day | summarize round(max(Price_ct_kWh), 2)),
         DayQuarterHours = toscalar(day | count)
